{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_5d3a5dea515c2f890b2e230e", "claim_ids": ["claim_2eebb4806759d445769fb031", "claim_362d2eda7cf48a2610b1af26"], "query_ids": ["q_502"], "claims": [{"claim_id": "claim_2eebb4806759d445769fb031", "quote": "February 11, 2021 - A battery supplier with an upcoming Georgia plant with the capability to supply up to 300,000 EVs annually has been banned from the U.S. by an ITC ruling.", "url": "https://www.greencarreports.com/news/1131259_itc-ruling-puts-georgia-ev-battery-plant-domestic-cell-supply-in-jeopardy", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "A battery supplier", "facility": "upcoming Georgia plant", "tariff_program": "ITC ruling", "legal_authority": "ITC ruling", "reported_policy_status": "banned"}}, {"claim_id": "claim_362d2eda7cf48a2610b1af26", "quote": "The immigration raid last week on an electric vehicle battery plant in Georgia owned by two South Korean manufacturers was yet another setback for what had been a fast-growing industry in the United States.", "url": "https://www.nytimes.com/2025/09/08/business/georgia-immigration-raid-ev-battery-plant-hyundai-lg.html", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "two South Korean manufacturers", "facility": "electric vehicle battery plant in Georgia", "country_of_origin": "South Korea"}}]}, {"pair_id": "conflict_8e6038f98bbd4574ef634de7", "claim_ids": ["claim_362d2eda7cf48a2610b1af26", "claim_7c8728274db16b1230c671e3"], "query_ids": ["q_502"], "claims": [{"claim_id": "claim_362d2eda7cf48a2610b1af26", "quote": "The immigration raid last week on an electric vehicle battery plant in Georgia owned by two South Korean manufacturers was yet another setback for what had been a fast-growing industry in the United States.", "url": "https://www.nytimes.com/2025/09/08/business/georgia-immigration-raid-ev-battery-plant-hyundai-lg.html", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "two South Korean manufacturers", "facility": "electric vehicle battery plant in Georgia", "country_of_origin": "South Korea"}}, {"claim_id": "claim_7c8728274db16b1230c671e3", "quote": "But the raid at the plant under construction in Ellabell, Ga., which is owned by the carmaker Hyundai and battery supplier LG Energy Solution, raised more risks for foreign manufacturers in the United States.", "url": "https://www.nytimes.com/2025/09/08/business/georgia-immigration-raid-ev-battery-plant-hyundai-lg.html", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "LG Energy Solution"}}]}, {"pair_id": "conflict_089c97ef4061fa23f905bbfd", "claim_ids": ["claim_1ad021a5d2385f779992fda0", "claim_5b4e7227fa2b4b5d88dc2438"], "query_ids": ["q_503"], "claims": [{"claim_id": "claim_1ad021a5d2385f779992fda0", "quote": "A new 25% tariff on imported auto parts officially took effect at 12:01 a.m. EDT on May 3.", "url": "https://www.automotive-fleet.com/news/tariff-update-may-30-tariff-shifts-shake-up-auto-industry-as-legal-trade-battles-evolve", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% tariff on imported auto parts", "effective_date": "May 3"}}, {"claim_id": "claim_5b4e7227fa2b4b5d88dc2438", "quote": "On May 29, a U.S. Court of Appeals temporarily reinstated certain tariffs after conflicting rulings created uncertainty in the auto industry.", "url": "https://www.automotive-fleet.com/news/tariff-update-may-30-tariff-shifts-shake-up-auto-industry-as-legal-trade-battles-evolve", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "certain tariffs", "legal_authority": "International Emergency Economic Powers Act", "effective_date": "May 29", "reported_policy_status": "temporarily reinstated"}}]}, {"pair_id": "conflict_8384925a419e4a2feb535db1", "claim_ids": ["claim_8b933ef0e670f3572750d9e6", "claim_a02af2f424a4156460c373cd"], "query_ids": ["q_503"], "claims": [{"claim_id": "claim_8b933ef0e670f3572750d9e6", "quote": "25% TARIFFS ON CANADIAN STEEL AND ALUMINUM PRODUCTS WILL GO INTO EFFECT.", "url": "https://www.youtube.com/watch?v=35hkflOV0Hg", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% TARIFFS ON CANADIAN STEEL AND ALUMINUM PRODUCTS", "duty_rate": "25%", "effective_date": "IN JUST A FEW HOURS"}}, {"claim_id": "claim_a02af2f424a4156460c373cd", "quote": "A 25% TARIFF ON STEEL AND ALUMINUM IS SET TO GO INTO PLACE ON WEDNESDAY.", "url": "https://www.youtube.com/watch?v=35hkflOV0Hg", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% TARIFF ON STEEL AND ALUMINUM", "duty_rate": "25%", "effective_date": "WEDNESDAY", "reported_policy_status": "SET TO GO INTO PLACE"}}]}, {"pair_id": "conflict_b79c96034f376fb25a827b8d", "claim_ids": ["claim_bb5d8bd3aa9e77fb802c6220", "claim_d4cdbba8690ec9dec19cb849"], "query_ids": ["q_503"], "claims": [{"claim_id": "claim_bb5d8bd3aa9e77fb802c6220", "quote": "Trump has imposed new 20% duties on Chinese imports, reinstated 25% tariffs on global steel and aluminum, and applied 25% tariffs on certain imports from Canada and Mexico that do not comply with a North American trade agreement over the U.S. fentanyl overdose crisis.", "url": "https://www.automotive-fleet.com/news/tariff-update-may-30-tariff-shifts-shake-up-auto-industry-as-legal-trade-battles-evolve", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Trump", "tariff_program": "new 20% duties on Chinese imports, reinstated 25% tariffs on global steel and aluminum, and applied 25% tariffs on certain imports from Canada and Mexico", "exporting_country": "Canada", "duty_rate": "25%"}}, {"claim_id": "claim_d4cdbba8690ec9dec19cb849", "quote": "Trump signed a proclamation last week to impose a 25 percent tariff on steel from every country except Canada and Mexico.", "url": "https://aldailynews.com/fear-steel-tariff-hurt-auto-industry-south", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"legal_authority": "proclamation", "duty_rate": "25 percent"}}]}, {"pair_id": "conflict_9851dd8369c2613565044dae", "claim_ids": ["claim_3d8a4382086e5189ebfd350d", "claim_759e14ec841b6d19b2f5b925"], "query_ids": ["q_504"], "claims": [{"claim_id": "claim_3d8a4382086e5189ebfd350d", "quote": "the Trump administration will potentially only be in power for approximately 3.5 more years and the tariff landscape may drastically change at that point, nullifying any investment decisions.", "url": "https://www.automotivelogistics.media/supply-chain/automotive-logistics-and-supply-chains-in-2025-tariff-turmoil-investment-uncertainty-and-further-cost-pressures/649740", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Trump tariff announcements", "reported_policy_status": "potentially only be in power for approximately 3.5 more years"}}, {"claim_id": "claim_759e14ec841b6d19b2f5b925", "quote": "Imported vehicle parts will face a 25% tariff, potentially raising production costs at Georgia’s auto plants.", "url": "https://www.fox5atlanta.com/news/trumps-tariff-plan-sparks-economic-uncertainty-georgia", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% tariff", "affected_product": "Imported vehicle parts"}}]}, {"pair_id": "conflict_945b1cb797c0845633229953", "claim_ids": ["claim_e0b419e72b29c66398925287", "claim_ee0ecda05c1e3aff0131d5b2"], "query_ids": ["q_504"], "claims": [{"claim_id": "claim_e0b419e72b29c66398925287", "quote": "Production lines move away from EVs to hybrid vehicles as", "url": "https://thecurrentga.org/2025/03/31/tariff-threat-casts-shadow-over-hyundais-plant-opening-party-in-bryan-county", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}, {"claim_id": "claim_ee0ecda05c1e3aff0131d5b2", "quote": "The week before the 2 April tariff announcement, Hyundai committed to a $21 billion investment through 2028 in the US. This included a new $7.6 billion Metaplant in Georgia, targeting 1.2 million annual units and 100,000 jobs and included vertical integration and localisation of steel, batteries and vehicle production.", "url": "https://www.automotivelogistics.media/supply-chain/automotive-logistics-and-supply-chains-in-2025-tariff-turmoil-investment-uncertainty-and-further-cost-pressures/649740", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai", "facility": "Metaplant in Georgia", "tariff_program": "Trump tariff announcements"}}]}, {"pair_id": "conflict_8f5f7438acf764e0bb00ac49", "claim_ids": ["claim_308073f842561b19f797bd14", "claim_b101d12ca13a6fc08e611b84"], "query_ids": ["q_505"], "claims": [{"claim_id": "claim_308073f842561b19f797bd14", "quote": "The tariffs are in addition to existing duties, which currently stand at a base rate of 2.5% for automotive imports.", "url": "https://www.ledger-enquirer.com/news/politics-government/article302957479.html", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "2.5%"}}, {"claim_id": "claim_b101d12ca13a6fc08e611b84", "quote": "German car brands like BMW, Mercedes-Benz, and Audi have a significant presence in the U.S. market and are subject to the 25% tariffs.", "url": "https://www.ledger-enquirer.com/news/politics-government/article302957479.html", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "BMW", "duty_rate": "25%"}}]}, {"pair_id": "conflict_51c1ebb663477806f4efc83c", "claim_ids": ["claim_c71f371c7d88e834f36ca982", "claim_d9021dcc7320bd5b8a989d52"], "query_ids": ["q_505"], "claims": [{"claim_id": "claim_c71f371c7d88e834f36ca982", "quote": "The 25% auto tariff could pose a major threat to automobile titans like Hyundai and Kia that have production plants in the state, said Jennifer Safavian, president and CEO of the trade group Autos Drive America.", "url": "https://pro.stateaffairs.com/ga/politics/georgia-tariffs-cars-lockheed-china", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Kia", "facility": "production plants"}}, {"claim_id": "claim_d9021dcc7320bd5b8a989d52", "quote": "The 25% auto tariff could pose a major threat to automobile titans like Hyundai and Kia that have production plants in the state", "url": "https://pro.stateaffairs.com/ga/politics/georgia-tariffs-cars-lockheed-china", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai", "facility": "production plants", "tariff_program": "25% tariff on imported cars and car parts", "duty_rate": "25%", "reported_policy_status": "Remaining in effect"}}]}, {"pair_id": "conflict_6787161de72a746f2aaf4627", "claim_ids": ["claim_6251ed3a5afd13dc03335679", "claim_d119bc054e534700289d9dc8"], "query_ids": ["q_507"], "claims": [{"claim_id": "claim_6251ed3a5afd13dc03335679", "quote": "The 15% tariff applied to South Korean imports is increasing the economic incentive for local production expansion.", "url": "https://finance.biggo.com/news/7c816f70-187d-4f54-84d6-c8c8f26bacb6", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "15%"}}, {"claim_id": "claim_d119bc054e534700289d9dc8", "quote": "Tariffs take effect this week, creating pricing instability across the auto industry.", "url": "https://www.facebook.com/quartznews/posts/hyundai-is-weighing-a-massive-expansion-of-its-georgia-car-plant-citing-tariffs-/1419057173423430", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Tariffs", "effective_date": "this week"}}]}]}

